def cc(n):
    s = ''
    while n != 0:
        s = str(n % 4) + s
        n //= 4
    return s


def f(n):
    s = cc(n)
    if sum(list(map(int, list(s)))) % 4 == 0:
        s = s.replace('0', '*').replace('3', '0').replace('*', '3')
        s += '21'
    else:
        s += '22'
        s = '11' + s[2:]
    return int(s, 4)


mi = float('inf')
ans = float('inf')
for i in range(1, 100000):
    if f(i) > 200:
        if f(i) < mi:
            mi = f(i)
            ans = i
print(ans)
